const TAX_RATE = 0.06;

function withTax(amount) {
  return Math.round(amount * (1 + TAX_RATE) * 100) / 100;
}

const SHIPPING = {
  standard: 8,
  express: 18,
  overnight: 38,
};

const FREE_SHIPPING_OVER = 199;

module.exports = { withTax, SHIPPING, FREE_SHIPPING_OVER };

